import{_ as n}from"./chunks/ha-label-erstellen.DlZFuxLI.js";import{_ as t,o as r,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"MQTT-Client","description":"Ausgewählte Home-Assistant-Werte live per MQTT übertragen und gezielt steuern.","frontmatter":{"title":"MQTT-Client","description":"Ausgewählte Home-Assistant-Werte live per MQTT übertragen und gezielt steuern."},"headers":[],"relativePath":"projects/mqtt-client/index.md","filePath":"projects/mqtt-client/index.md","lastUpdated":1794133563000}'),s={name:"projects/mqtt-client/index.md"};function l(d,e,u,o,h,g){return r(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="mqtt-client-0-1-16" tabindex="-1">MQTT-Client 0.1.36 <a class="header-anchor" href="#mqtt-client-0-1-16" aria-label="Permalink to &quot;MQTT-Client 0.1.36 {#mqtt-client-0-1-16}&quot;">​</a></h1><p>Ausgewählte HA-Zustände und Attribute gezielt an einen externen MQTT-Broker übertragen. MQTT-Client und JavaScript-Helfer 0.1.34 ergänzen eine wählbare flache VIS-2-Struktur mit kurzen Namen. Für diese Option muss der vollständige Helfer im ioBroker-JavaScript-Adapter ersetzt werden; ein HA-App-Update allein ersetzt das dort gespeicherte Skript nicht.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.36" target="_blank" rel="noreferrer">Release 0.1.36</a></p><p><strong>App 0.1.35:</strong> Auch eine gleichzeitig manuell und per Label ausgewählte Lampe darf vorübergehend im HA-Abgleich fehlen. Der Auswahlkatalog bleibt dann verfügbar. Der JavaScript-Helfer bleibt auf <strong>0.1.34</strong>.</p><h2 id="settings-persistence-0136" tabindex="-1">Neu in 0.1.36: Einstellungen nach Updates erhalten <a class="header-anchor" href="#settings-persistence-0136" aria-label="Permalink to &quot;Neu in 0.1.36: Einstellungen nach Updates erhalten {#settings-persistence-0136}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Erfolgreicher Neustarttest am 07.11.2026</p><p>Der Nutzer hat nach erneutem Speichern der Einstellungen beim Umstieg auf <strong>0.1.36</strong> die MQTT-Client-App neu gestartet und bestätigt: <strong>Der Messwerte-Haken bleibt gesetzt, die MQTT-Struktur bleibt „Flach mit kurzen Namen“.</strong> Damit ist der praktische Neustarttest erfolgreich. Ein weiterer Versionswechsel wurde dabei nicht geprüft; der praktische Update-Test auf die nächste Version steht noch aus.</p></div><p><strong>Gespeicherte App-Einstellungen bleiben jetzt auch erhalten, wenn der Home-Assistant-Supervisor beim Update seine Optionsdatei neu erzeugt.</strong> Das betrifft insbesondere den Messwerte-Haken und die MQTT-Struktur für neue Entitäten, aber auch die übrigen in der App gespeicherten Einstellungen und Zugangsdaten. Die App sichert sie unabhängig in der privaten Datei <code>/data/mqtt-settings.json</code>. Die MQTT-Pfadzuordnungen bleiben weiterhin in <code>/data/mqtt-routes.json</code>; vorhandene Datenpunkte und VIS-2-Verknüpfungen werden nicht geändert.</p><p><strong>Einmaliger Umstieg von 0.1.35 oder älter:</strong> Vor dem Update die Einstellungen in der App exportieren. Falls sie beim ersten Wechsel bereits zurückgesetzt wurden, die Sicherung nach dem Update wieder importieren oder die beiden Optionen einmal erneut wählen und <strong>Speichern und verbinden</strong> drücken. Schon verlorene Einstellungen können nicht zuverlässig rekonstruiert werden; zusätzliche Messwerte werden nicht ungefragt aktiviert.</p><p>Die Einstellungen bevorzugt in der App ändern. Tatsächlich geänderte Supervisor-Konfigurationswerte werden beim Neustart übernommen; unveränderte Supervisor-Standardwerte setzen App-Auswahlen nicht zurück. Soll eine App-Auswahl ausdrücklich auf ihren Standard zurück, dies in der App wählen und speichern. Die vorhandene Einstellungssicherung bleibt verwendbar und enthält weiterhin keine Passwörter oder privaten TLS-Schlüssel. Der JavaScript-Helfer bleibt <strong>0.1.34</strong>; hierfür muss er nicht erneut ersetzt werden.</p><p>Hintergrund: Der Supervisor verwaltet <code>/data/options.json</code>; für eigene dauerhafte Daten ist das private <code>/data</code>-Verzeichnis vorgesehen. <a href="https://contributors.home-assistant.io/apps/reference/environment/" target="_blank" rel="noreferrer">Offizielle HA-Dokumentation</a>.</p><h2 id="mqtt-layout-0134" tabindex="-1">Neu in 0.1.34: flache MQTT-Pfade nur für neue Entitäten <a class="header-anchor" href="#mqtt-layout-0134" aria-label="Permalink to &quot;Neu in 0.1.34: flache MQTT-Pfade nur für neue Entitäten {#mqtt-layout-0134}&quot;">​</a></h2><p>Unter <strong>Übertragung und TLS → MQTT-Struktur für neue Entitäten</strong> kann <strong>Flach mit kurzen Namen</strong> gewählt werden. Standard bleibt die bisherige Struktur. Danach <strong>Speichern und verbinden</strong>. Die Einstellung gilt für erstmals ausgewählte manuelle Entitäten und neue Label-Mitglieder, einschließlich optionaler Gerätemesswerte.</p><p>Bereits bekannte Entitäten behalten ihre bisherigen Pfade. Die Zuordnung wird dauerhaft in <code>/data/mqtt-routes.json</code> gespeichert und ist in der exportierten Einstellungssicherung enthalten. Auch nach Entfernen und erneutem Auswählen eines Labels, Umbenennen, Neustart oder Update wird derselbe Pfad verwendet. Beim ersten Upgrade werden vorhandene Auswahlen und erfasste Topics als Bestand übernommen; die bestehende Label-Auswahl wird beim ersten erfolgreichen Abgleich gesichert. Diese Datei nicht löschen. Eine Rückstellung auf die bisherige Struktur migriert keine bereits zugeordneten Entitäten.</p><p>Beispiel für neue flache MQTT-Topics:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ha_external/geraet/schalter</span></span>
<span class="line"><span>ha_external/geraet/schalter_set</span></span>
<span class="line"><span>ha_external/geraet/schalter_attribute/device_class</span></span>
<span class="line"><span>ha_external/geraet/energie</span></span>
<span class="line"><span>ha_external/geraet/leistung</span></span>
<span class="line"><span>ha_external/geraet/licht_brightness</span></span>
<span class="line"><span>ha_external/geraet/licht_brightness_set</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Alte Topics wie <code>ha_external/geraet/switch/state</code> und <code>…/switch/set</code> bleiben parallel gültig. Vergebene kurze Namen werden bei Kollisionen eindeutig ergänzt. Vorhandene Datenpunkte, Werte, Aliase und VIS-2-Verknüpfungen werden weder umbenannt noch gelöscht.</p><p><strong>Vor Aktivierung den vollständigen JavaScript-Helfer 0.1.34 installieren und eigene Einstellungen übernehmen.</strong> Er liest beide MQTT-Strukturen anhand des übertragenen Auswahlkatalogs mit exakten Status- und Rückkanalpfaden. Erst Vorschau prüfen, dann <code>mode: &#39;apply&#39;</code>. Ältere Helfer erkennen die neuen flachen MQTT-Pfade nicht. <code>virtualLayout: &#39;flat&#39;</code> ist davon unabhängig: Diese Helferoption bestimmt nur die Darstellung unter <code>0_userdata.0.ugso_mqtt</code>. Die bisherigen manuellen Rollen und Verknüpfungen bleiben geschützt.</p><h2 id="enable-device-readings" tabindex="-1">Wichtig: Zusätzliche Gerätemesswerte ausdrücklich aktivieren <a class="header-anchor" href="#enable-device-readings" aria-label="Permalink to &quot;Wichtig: Zusätzliche Gerätemesswerte ausdrücklich aktivieren {#enable-device-readings}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Wichtig: Zusätzliche Gerätemesswerte ausdrücklich aktivieren</p><p><strong>Ein Label allein aktiviert die zusätzlichen Messwerte nicht.</strong> Unter <strong>Übertragung und TLS</strong> muss der Haken <strong>„Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen“</strong> gesetzt und anschließend <strong>„Speichern und verbinden“</strong> gedrückt werden. Ohne diesen Haken werden Energie, Spannung, Strom und Leistung nicht automatisch zum gelabelten Schalter ergänzt. Bereits manuell ausgewählte Werte bleiben davon unabhängig.</p></div><p>Erfasst werden unterstützte und in HA aktivierte Sensoren mit derselben HA-Gerätezuordnung, sofern vorhanden. Es werden keine Messwerte erzeugt, die das Gerät nicht bereitstellt. <strong>„Zugehörige Messwerte prüfen“</strong> zeigt Erkennung und Ausschlussgründe. Schaltwerte haben Vorrang; Messwerte dürfen verzögert folgen.</p><h2 id="javascript-vis2-helper" tabindex="-1">Besonders für VIS 2: der ioBroker-JavaScript-Helfer <a class="header-anchor" href="#javascript-vis2-helper" aria-label="Permalink to &quot;Besonders für VIS 2: der ioBroker-JavaScript-Helfer {#javascript-vis2-helper}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Besonders für VIS 2: der ioBroker-JavaScript-Helfer</p><p>Das mitgelieferte <strong>JavaScript wird im ioBroker-JavaScript-Adapter ausgeführt, nicht in Home Assistant</strong>. Es legt virtuelle Datenpunkte unter <code>0_userdata.0.ugso_mqtt</code> an: <strong>ein Datenpunkt pro Wert für Anzeige und Bedienung</strong>, obwohl MQTT getrennte <code>state</code>- und <code>set</code>-Topics verwendet. Unterstützte Schalter und Light-Werte erhalten den passenden Rückkanal; Messwerte bleiben lesend. Anhand geeigneter HA-Metadaten werden Datentypen, Einheiten und eindeutige Rollen zugeordnet. Eine Schaltanforderung ist erst nach tatsächlicher HA-Rückmeldung bestätigt.</p><p><strong>Zuerst Vorschau prüfen, dann <code>mode: &#39;apply&#39;</code> einstellen.</strong> In der Vorschau werden nur fehlende eigene Basisordner/Sicherungsdatenpunkte angelegt; die virtuellen VIS-2-Werte entstehen im Anwendungsmodus. Für die Anlage muss <strong>setObject</strong> in den Adaptereinstellungen erlaubt sein. Bestehende Werte und manuell gesetzte Rollen bleiben geschützt. Die HA-App und der Helfer liegen für diese Erweiterung bei <strong>0.1.33</strong>. Für die flache Struktur den vollständigen Helfer in ioBroker ersetzen; ein App-Update allein genügt dafür nicht. Ohne Helfer ist die reine MQTT-Übertragung weiterhin nutzbar.</p></div><h2 id="neu-in-0-1-33-flache-vis-2-struktur-mit-kurzen-namen" tabindex="-1">Neu in 0.1.33: flache VIS-2-Struktur mit kurzen Namen <a class="header-anchor" href="#neu-in-0-1-33-flache-vis-2-struktur-mit-kurzen-namen" aria-label="Permalink to &quot;Neu in 0.1.33: flache VIS-2-Struktur mit kurzen Namen&quot;">​</a></h2><p><strong>Den vollständigen JavaScript-Helfer 0.1.33 ersetzen und eigene Einstellungen übernehmen.</strong> Im Einstellungsblock wählt <code>virtualLayout: &#39;nested&#39;</code> die bisherige Struktur (Standard); <code>virtualLayout: &#39;flat&#39;</code> legt kurze Datenpunkte direkt unter dem Geräteordner an, etwa <code>schalter</code>, <code>energie</code>, <code>leistung</code>, <code>spannung</code>, <code>stromstaerke</code>. Bei Lampen kommen passende Werte wie <code>helligkeit</code>, <code>farbe</code>, <code>effekt</code> und <code>farbtemperatur</code> hinzu. Gleichartige oder belegte Namen erhalten eindeutige Zusätze wie <code>leistung_2</code>; einmal vergebene Zuordnungen bleiben im Sicherungsjournal erhalten.</p><p>Zuerst im Vorschaumodus prüfen, anschließend <code>mode: &#39;apply&#39;</code> wählen. Ein Layoutwechsel löscht oder verschiebt keine vorhandenen Datenpunkte. Bereits vom Helfer angelegte alte und neue IDs werden weiter aktualisiert und behalten ihre freigegebenen Rückkanäle; vorhandene VIS-2-Verknüpfungen können bleiben. Deshalb bleiben alte Ordner zunächst auch sichtbar. Fremde Objekte und manuelle Rollen werden nicht überschrieben, MQTT-Topics bleiben unverändert. Zur Rückkehr die Option mit dem neuen Helfer auf <code>nested</code> stellen; die alte Helferdatei 0.1.27 kann Journale mit flachen Einträgen nicht lesen.</p><h2 id="neu-in-0-1-32-zusatzliche-messwerte-deutlich-markieren" tabindex="-1">Neu in 0.1.32: zusätzliche Messwerte deutlich markieren <a class="header-anchor" href="#neu-in-0-1-32-zusatzliche-messwerte-deutlich-markieren" aria-label="Permalink to &quot;Neu in 0.1.32: zusätzliche Messwerte deutlich markieren&quot;">​</a></h2><p>Die Option <strong>„Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen“</strong> ist gelb hervorgehoben. Die Markierung aktiviert den Haken nicht: Gewünschte Auswahl setzen und <strong>„Speichern und verbinden“</strong> drücken. Bestehende Einstellungen bleiben erhalten. TLS und Zertifikate sind weiterhin separat einklappbar.</p><h2 id="neu-in-0-1-31-tls-und-zertifikate-separat-einklappen" tabindex="-1">Neu in 0.1.31: TLS und Zertifikate separat einklappen <a class="header-anchor" href="#neu-in-0-1-31-tls-und-zertifikate-separat-einklappen" aria-label="Permalink to &quot;Neu in 0.1.31: TLS und Zertifikate separat einklappen&quot;">​</a></h2><p><strong>TLS und Zertifikate</strong> ist jetzt ein eigener, per Maus und Tastatur bedienbarer Klappbereich. Die Schaltfläche zeigt auch geschlossen, ob TLS ausgewählt ist. Beim Auf-/Zuklappen werden weder TLS noch gespeicherte Zertifikate oder Zugangsdaten verändert. Nach Laden und Speichern bleibt der Bereich geschlossen; Übertragungseinstellungen und die beiden Aktionsschaltflächen bleiben sichtbar. Der <a href="/blog/snippets/iobroker-blockly#mqtt-vis2-helper">neue Blogeintrag zum JavaScript-Helfer</a> erklärt Zweck, Einrichtung, Status/Rückkanal und Sicherung und enthält das vollständige unveränderte Skript 0.1.27 mit Kopierbutton und Download.</p><h2 id="neu-in-0-1-30-zugangsdaten-einklappen" tabindex="-1">Neu in 0.1.30: Zugangsdaten einklappen <a class="header-anchor" href="#neu-in-0-1-30-zugangsdaten-einklappen" aria-label="Permalink to &quot;Neu in 0.1.30: Zugangsdaten einklappen&quot;">​</a></h2><p><strong>Zugangsdaten</strong> besitzt jetzt eine eigene Auf-/Zuklapp-Schaltfläche, auch per Tastatur bedienbar. Bei vorhandenem Broker bleiben IP, Port, Benutzername und Passwort nach Laden und Speichern eingeklappt. Fehlen Pflichtangaben, wird der Bereich zur Eingabe geöffnet. <strong>Übertragung und TLS</strong>, <strong>Speichern und verbinden</strong> und <strong>Aktuell übertragene Werte</strong> bleiben sichtbar. Einstellungen und Zugangsdaten werden nicht verändert. Die Priorisierung aus 0.1.29 und Helfer 0.1.27 bleiben erhalten. Der Nutzer hat die Schalt-Rückmeldung mit ungefähr einer halben Sekunde Verzögerung als erfolgreich bestätigt. Auch die Zigbee-Lampe wurde erfolgreich geprüft: Rückmeldung funktioniert, die Helligkeit folgt HA auf 100 %.</p><h2 id="neu-in-0-1-29-schaltwerte-vor-messwerten" tabindex="-1">Neu in 0.1.29: Schaltwerte vor Messwerten <a class="header-anchor" href="#neu-in-0-1-29-schaltwerte-vor-messwerten" aria-label="Permalink to &quot;Neu in 0.1.29: Schaltwerte vor Messwerten&quot;">​</a></h2><p><strong>Die HA-MQTT-Client-App auf 0.1.29 aktualisieren; der ioBroker-Helfer 0.1.27 bleibt unverändert.</strong> Schaltzustände, Kontakte und Befehlsrückmeldungen werden vor Messwerten behandelt. Ihre Veröffentlichung wartet nicht auf die Publish-Pause. Bereits laufende Übertragungen werden abgeschlossen; zwischen Nachrichten geben Messwert-/Attributpakete für dringende Zustände und Schaltbefehle nach. Wenn mindestens 32 Ereignisse warten, werden Sensor-Zwischenstände in begrenzten Paketen auf den jeweils letzten Zustand zusammengefasst. Normale Schaltfolgen bleiben erhalten. Zusätzlich liest der Kontrollabgleich auch bei bestehender Live-Verbindung den tatsächlichen HA-Zustand im vorhandenen <code>poll_interval</code> (Standard 5 Sekunden). Unveränderte Werte werden nicht erneut veröffentlicht. <strong>Übertragung und TLS</strong> sowie die <strong>Publish-Pause für Messwerte und Attribute</strong> sind direkt sichtbar; Zugangsdaten bleiben separat einklappbar. Die Statuszeile unterscheidet <strong>Wartend</strong>, <strong>Zusammengefasst</strong>, <strong>HA-Eingang</strong> und den fortlaufenden Zähler <strong>Gesendet</strong>. Bestehende Einstellungen und Werte bleiben erhalten. Für die Prüfung den Kontrollabgleich auf 5 Sekunden lassen und ein unkritisches Relais in HA schalten. Erst eine tatsächliche HA-Rückmeldung führt zu <code>ack: true</code>; die Broker-Übergabe allein genügt nicht. Lokal geprüft, Bestätigung der Verzögerung auf dem Nutzersystem steht noch aus.</p><p>Schalter werden über die Domain <code>switch.*</code> erkannt und benötigen weder Geräteklasse noch Einheit. Lampen verwenden <code>light.*</code>. Die aktivierte automatische Messwertauswahl bleibt auf dieselbe HA-Gerätezuordnung beschränkt. Für Sensoren gilt zuerst <code>device_class</code>; fehlt sie, werden eindeutige Einheiten aus <code>unit_of_measurement</code> wie W/kW/MW, V/mV/kV, A/mA und Wh/kWh/MWh verwendet. Vorhandene Klassen werden nicht überschrieben; ähnliche Namen oder ein mehrdeutiges Prozentzeichen genügen nicht. Unter <strong>Zugehörige Messwerte prüfen</strong> zeigt eine schreibgeschützte Prüfung die erkannten Sensoren und Ausschlussgründe, etwa fehlende Gerätezuordnung, deaktivierte Entität oder ungeeignete Klasse/Einheit. Messwerte dürfen hinter Schaltwerten warten. Einstellungen, Zugangsdaten und bestehende Werte bleiben erhalten.</p><h2 id="neu-in-0-1-28-ha-live-ruckmeldungen-ohne-fremde-ereignisflut" tabindex="-1">Neu in 0.1.28: HA-Live-Rückmeldungen ohne fremde Ereignisflut <a class="header-anchor" href="#neu-in-0-1-28-ha-live-ruckmeldungen-ohne-fremde-ereignisflut" aria-label="Permalink to &quot;Neu in 0.1.28: HA-Live-Rückmeldungen ohne fremde Ereignisflut&quot;">​</a></h2><p>Diese Korrektur betrifft die <strong>MQTT-Client-App in Home Assistant</strong>: auf 0.1.28 aktualisieren und die App neu starten. Der ioBroker-Helfer 0.1.27 kann unverändert bleiben; sein Austausch allein behebt den Empfang von HA-Ereignissen nicht. Bei aktiver Label-Auswahl werden nur noch Ereignisse tatsächlich ausgewählter Entitäten und ihrer aktivierten Gerätemesswerte eingereiht. Ereignisse des übrigen HA-Bestands können die Warteschlange nicht mehr füllen. Wenn Labels oder Gerätezuordnungen geändert werden, lädt der Client frische HA-Zustände. Ältere gepufferte Zustände mit überholtem <code>last_updated</code> werden nach einem Abgleich verworfen; normale zeitlich geordnete Änderungen bleiben erhalten. Der Überlastzähler zählt seit dem App-Start und meldet weiterhin echte Überläufe ausgewählter Ereignisse. Die eingestellte Publish-Pause und alle Zugangsdaten/Auswahlen bleiben erhalten; ein großer erster Abgleich kann weiterhin länger dauern. Nach abgeschlossenem Erstabgleich ein unkritisches Relais in HA schalten und prüfen, ob MQTT und der virtuelle ioBroker-Status zeitnah folgen. Live-Bestätigung auf dem Nutzersystem steht noch aus.</p><h2 id="neu-in-0-1-27-ruckkanal-ohne-retain" tabindex="-1">Neu in 0.1.27: Rückkanal ohne Retain <a class="header-anchor" href="#neu-in-0-1-27-ruckkanal-ohne-retain" aria-label="Permalink to &quot;Neu in 0.1.27: Rückkanal ohne Retain&quot;">​</a></h2><p>Schaltbefehle werden jetzt gezielt über die ioBroker-MQTT-Schnittstelle <code>sendMessage2Client</code> mit <strong><code>retain: false</code></strong> veröffentlicht. Normale Schreibzugriffe auf MQTT-<code>set</code>-Datenpunkte können im Servermodus mit gesetztem Retain-Flag beim Client ankommen. Der HA-Client verwirft solche Befehle weiterhin, damit beim Verbinden keine alten Schaltaufträge ausgeführt werden. Globale Broker-Einstellungen und MQTT-Datenpunktwerte bleiben erhalten. Der Helfer prüft den Befehlstopic gegen den zugehörigen Statustopic und verwendet <code>native.topic</code>, nicht aus Objekt-IDs erratene Pfade. In VIS 2 weiterhin ausschließlich den virtuellen Datenpunkt unter <code>0_userdata.0.ugso_mqtt</code> mit <code>ack: false</code> bedienen und <code>mode: &#39;apply&#39;</code> verwenden. Die Logzeile <code>Command handed to MQTT adapter (retain=false)</code> bestätigt nur die Übergabe; erst ein neuer HA-Status bestätigt den Vorgang. Der rohe MQTT-<code>set</code>-Wert muss dabei nicht wechseln. Keine automatischen Wiederholungen; Fehler oder fehlende HA-Bestätigung bleiben als unbestätigt erkennbar. Für diese Korrektur die vollständige Helferdatei ersetzen und eigene Einstellungen übernehmen.</p><h2 id="neu-in-0-1-26-automatische-basisanlage" tabindex="-1">Neu in 0.1.26: automatische Basisanlage <a class="header-anchor" href="#neu-in-0-1-26-automatische-basisanlage" aria-label="Permalink to &quot;Neu in 0.1.26: automatische Basisanlage&quot;">​</a></h2><p>Fehlende eigene Basisordner (<code>virtualRoot</code>, <code>aliasRoot</code>) und beide Sicherungsdatenpunkte (<code>virtualBackupId</code>, <code>backupId</code>) werden jetzt beim Start in <strong>jedem Modus</strong> automatisch angelegt, auch in <code>preview</code> und <code>restore</code>. Vorhandene Ordner, Sicherungen, Werte und manuelle Rollen werden nicht überschrieben. Neue Journale enthalten gültige leere Strukturen. Für die Basisanlage muss <code>setObject</code> in der JavaScript-Instanz auch in der Vorschau erlaubt sein. Fehlende Freigaben oder kollidierende Pfade werden als Fehler gemeldet. Die Vorschau legt keine steuerbaren VIS-2-Datenpunkte an und ändert keine MQTT-Rollen oder Gerätewerte; dafür nach Prüfung <code>mode: &#39;apply&#39;</code> verwenden. Die ereignisgesteuerte Verarbeitung aus 0.1.25 bleibt erhalten.</p><h2 id="automatische-vis-2-datenpunkte-ab-0-1-24" tabindex="-1">Automatische VIS-2-Datenpunkte ab 0.1.24 <a class="header-anchor" href="#automatische-vis-2-datenpunkte-ab-0-1-24" aria-label="Permalink to &quot;Automatische VIS-2-Datenpunkte ab 0.1.24&quot;">​</a></h2><p>Der kombinierte ioBroker-Helfer erstellt virtuelle Datenpunkte mit Status und Rückkanal in einem. Unterstützt werden Switches, Light-Werte und weitere freigegebene Zahl-/Auswahl-/Textkanäle; Datum und Messwerte bleiben lesend. Die ursprünglichen MQTT-Werte, Einstellungen und vorhandenen Aliase bleiben erhalten. Vorschau, automatische Sicherung, Typ-/Grenzwertprüfung und Schutz vor Rückkopplungen sind enthalten. Die Warnungen beim Lesen fehlender optionaler Datenpunkte sind korrigiert. Für die APIs von JavaScript-Adapter <strong>10.4.10</strong> vorbereitet, noch kein neuer realer Installationstest.</p><p><a href="./iobroker-roles#vis2">Einrichtung und Zuordnungstabelle</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.24" target="_blank" rel="noreferrer">Release 0.1.24</a></p><h2 id="iobroker-rollenzuordnung-ab-0-1-23" tabindex="-1">ioBroker-Rollenzuordnung ab 0.1.23 <a class="header-anchor" href="#iobroker-rollenzuordnung-ab-0-1-23" aria-label="Permalink to &quot;ioBroker-Rollenzuordnung ab 0.1.23&quot;">​</a></h2><p>Ein optionales JavaScript ordnet Datum, Zeitstempel und eindeutige Messwerte passenden ioBroker-Rollen zu. Vorschau, Sicherung vor Änderungen und Wiederherstellung sind enthalten. Vorhandene Werte, Zugangsdaten und manuelle Spezialrollen bleiben erhalten. Schreibbare MQTT-Messwerte erhalten lesende Aliase. Das Skript lässt abweichende Datentypen, Einheiten und mehrdeutige Klassen aus.</p><p><a href="./iobroker-roles">Installation und vollständige Zuordnung HA → ioBroker</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.23" target="_blank" rel="noreferrer">Release 0.1.23</a></p><h2 id="neu-in-0-1-22" tabindex="-1">Neu in 0.1.22 <a class="header-anchor" href="#neu-in-0-1-22" aria-label="Permalink to &quot;Neu in 0.1.22&quot;">​</a></h2><p>Die Label-Auswahl aktiviert jetzt den Zustand, vorhandene Standardattribute und passende Rückkanäle steuerbarer Entitäten. Schalter erhalten automatisch <code>&lt;base&gt;/set</code> für <code>ON</code>/<code>OFF</code>; Zahlen, Selects und Taster verwenden ihre unterstützten Befehle. Es werden beim Einrichten keine Schaltbefehle gesendet. Retain-Befehle, leere Befehle und ungültige Werte werden verworfen.</p><p>Bei Lampen entstehen nur die von HA gemeldeten Kanäle:</p><table tabindex="0"><thead><tr><th>Kanal unter <code>&lt;base&gt;</code></th><th>Wert und Rückkanal</th></tr></thead><tbody><tr><td><code>brightness/state</code>, <code>brightness/set</code></td><td>Helligkeit 0–100 %</td></tr><tr><td><code>rgb_color/state</code>, <code>rgb_color/set</code></td><td>JSON <code>[255,128,0]</code>, Komponenten 0–255</td></tr><tr><td><code>effect/state</code>, <code>effect/set</code></td><td>Effektname aus der gemeldeten Effektliste</td></tr><tr><td><code>color_temp_kelvin/state</code>, <code>color_temp_kelvin/set</code></td><td>Ganze Kelvinzahl innerhalb der gemeldeten Grenzen</td></tr></tbody></table><p><code>&lt;base&gt;</code> ist das bestehende Topic ohne <code>/state</code>. Effektliste, unterstützte Farbmodi und minimale/maximale Kelvinwerte werden als Attribute nur gelesen. Manuell ausgewählte HA-Attribute behalten ihren Pfad und ihre Einheit: <code>attribute/brightness</code> bleibt beispielsweise 0–255.</p><p>Unter <strong>Übertragung und TLS</strong> kann <strong>Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen</strong> aktiviert werden. <code>label_device_readings</code> ist standardmäßig <code>false</code>. Berücksichtigt werden Energie, Spannung, Strom, Leistung, Temperatur, Feuchtigkeit und Batterie sowie ein vorhandener Batterie-leer-Sensor. Die Zuordnung erfolgt ausschließlich über dieselbe HA-Geräte-ID. Es werden keine Schwellwerte erfunden oder ähnlich benannte Geräte zusammengefasst. Diese zusätzlichen Sensoren erhalten keine Rückkanäle.</p><p>Automatisch übertragen werden vorhandene Standardangaben wie Name, Geräteklasse, Einheit und Zustandsklasse sowie notwendige Auswahl-/Grenzwerte. Andere Attribute bleiben manuell auswählbar. <code>device_class</code> wird als Metadatum übertragen; die ioBroker-Rolle, etwa <code>date</code>, wird dadurch nicht automatisch geändert.</p><p>Das Werte-Popup zeigt auch automatische Attribute, Light-Werte und aktive Rückkanäle mit ihrer Herkunft. Nach Entfernen des Labels entfallen automatische Werte und Rückkanäle beim nächsten Abgleich; wartende Befehle werden vor der Ausführung erneut geprüft. Manuelle Auswahlen und Zugangsdaten bleiben erhalten. Alte Retain-Werte werden erst über die bestätigte Topic-Bereinigung entfernt.</p><p>Lokal mit simuliertem HA und Broker geprüft; kein neuer Gerätetest auf HA. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.22" target="_blank" rel="noreferrer">Release 0.1.22</a></p><h2 id="aktuell-ubertragene-werte" tabindex="-1">Aktuell übertragene Werte <a class="header-anchor" href="#aktuell-ubertragene-werte" aria-label="Permalink to &quot;Aktuell übertragene Werte&quot;">​</a></h2><p>Ab <strong>0.1.21</strong> klappen nur die Zugangsdaten automatisch ein. <strong>Übertragung und TLS</strong> ist davon getrennt erreichbar. <strong>Speichern und verbinden</strong> und <strong>Aktuell übertragene Werte</strong> bleiben gleich groß in einer Reihe sichtbar.</p><p>Der zweite Button öffnet eine durchsuchbare, scrollbare Liste aller aktuell ausgewählten States und Attribute, einschließlich der per HA-Label ausgewählten States. Doppelte States werden zusammengeführt. Die Herkunft wird als beschriftetes Badge gezeigt: <strong>Label</strong> blau, <strong>Manuell</strong> grün, <strong>Beides</strong> violett. Seit 0.1.22 werden auch automatische Standardattribute und Light-Werte angezeigt.</p><p>Jede Zeile zeigt Name, Entitäts-ID, gegebenenfalls Attribut, aktuellen Wert und MQTT-Topic. Die letzte erfolgreiche Brokerbestätigung enthält Zeitpunkt und gesendeten Wert; noch nicht bestätigte Werte sind gekennzeichnet und Fehler separat rot markiert. Die Bestätigung belegt die Annahme durch den Broker, nicht die Verarbeitung durch ioBroker oder ein Zielgerät. Im geöffneten Popup erfolgt alle drei Sekunden eine Aktualisierung, zusätzlich über <strong>Aktualisieren</strong>. Die Übersicht gilt für die laufende Verbindung und wird bei deren Neustart zurückgesetzt. Zugangsdaten und Einstellungen werden weder geändert noch in dieser Liste ausgegeben. Lokal mit manuellen/Label-Auswahlen, Attributen, Bestätigungsfehlern und Mobilansicht geprüft. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.21" target="_blank" rel="noreferrer">Release 0.1.21</a></p><p><strong>0.1.20:</strong> Die Verbindungseinstellungen sind unter <strong>Zugangsdaten</strong> einklappbar. Zur Ersteinrichtung bleibt der Bereich offen. Mit gespeicherter Brokeradresse klappt er nach dem Laden und erfolgreichen Speichern automatisch zu. Ein Klick auf den Titel öffnet ihn wieder. Speicher- und Fehlermeldungen bleiben sichtbar; Einstellungen und Zugangsdaten bleiben erhalten. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.20" target="_blank" rel="noreferrer">Release 0.1.20</a></p><p><strong>0.1.19</strong> ergänzt die Zeilentrennung in der Übertragungsliste: Der Name steht über der Zusammenfassung aus State, ausgewählten Attributen und Rückbefehl. <strong>Bearbeiten</strong> bleibt rechts. Auch diese Ansicht wurde lokal bei 1300 und 390 Pixeln Breite geprüft. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.19" target="_blank" rel="noreferrer">Release 0.1.19</a></p><p>MQTT-Client überträgt ausgewählte Geräte, Zustände und Attribute aus Home Assistant an einen externen MQTT-Broker, beispielsweise den MQTT-Adapter von ioBroker. Statt sämtliche HA-Entitäten zu spiegeln, wählst du die benötigten Werte selbst aus. Der vorhandene HA-Broker bleibt bestehen. Die App liest direkt aus HA; sie ist keine Broker-Bridge.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/mqtt_client" target="_blank" rel="noreferrer">Quellcode und Konfigurationsreferenz</a> · <a href="/en/projects/mqtt-client/">English documentation</a></p><h2 id="einrichtung-und-auswahl" tabindex="-1">Einrichtung und Auswahl <a class="header-anchor" href="#einrichtung-und-auswahl" aria-label="Permalink to &quot;Einrichtung und Auswahl&quot;">​</a></h2><p>Seit <strong>0.1.18</strong> sind die Angaben im Geräte-Popup klar getrennt: <strong>Name</strong> in der ersten Zeile, <strong>Entitäts-ID</strong> in der zweiten und <strong>Zieltyp mit Attributanzahl</strong> in der dritten. Lange Namen und IDs werden umgebrochen; der aktuelle State bleibt rechts. Die Trennung bleibt auch nach einer Änderung der Auswahl erhalten. Die Darstellung wurde lokal bei 1300 und 390 Pixeln Breite geprüft. Einstellungen, Zugangsdaten und die Auswahl der übertragenen Werte bleiben beim Update erhalten. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.18" target="_blank" rel="noreferrer">Release 0.1.18</a></p><ol><li><code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> im Home-Assistant-App-Store hinzufügen.</li><li><strong>MQTT-Client</strong> installieren und starten; unterstützt werden amd64 und aarch64.</li><li>Die Weboberfläche öffnen und Host, Port, Benutzer und Passwort des externen Brokers speichern. Ohne TLS ist der Standardport 1883.</li><li>Links ein Gerät auswählen. Im Dialog sind seine Entitäten nach Steuerung, Sensoren, Konfiguration und Diagnose gruppiert. Die Suche findet auch Entitäten innerhalb eines Geräts.</li><li>Die gewünschten Werte und Attribute auswählen. Das Kontrollkästchen rechts in einer Wertzeile überträgt den Zustand einschließlich aller Attribute; die Geräteauswahl kann sämtliche Werte des Geräts übernehmen.</li></ol><p>Änderungen werden unmittelbar übernommen. Ein zusätzlicher HA-Zugriffstoken ist nicht nötig: Die App verwendet den Supervisor-Zugang zur HA-Core-API. Für mehrere Instanzen unterschiedliche Client-IDs und Themenpräfixe verwenden.</p><h2 id="weiterleitung-per-label" tabindex="-1">Weiterleitung per Home-Assistant-Label <a class="header-anchor" href="#weiterleitung-per-label" aria-label="Permalink to &quot;Weiterleitung per Home-Assistant-Label {#weiterleitung-per-label}&quot;">​</a></h2><p><img src="`+n+'" alt="Home Assistant: Dialog zum Anlegen eines neuen Labels"></p><p><em>Beispiel in Home Assistant: Das Label heißt hier „zu mqtt client“. Verwende im MQTT-Client die ID des Labels, das du angelegt hast.</em></p><ol><li><strong>Label anlegen:</strong> Gehe in Home Assistant zu <strong>Einstellungen → Bereiche, Labels und Zonen → Labels</strong>. Erstelle das Label <strong>zu mqtt client</strong> wie im Screenshot.</li><li><strong>Label-ID ablesen:</strong> Öffne <strong>Einstellungen → Werkzeuge → Vorlage</strong> (bei älteren Versionen <strong>Entwicklerwerkzeuge → Vorlage</strong>). Gib die Vorlage unten ein und kopiere das Ergebnis, beispielsweise <code>zu_mqtt_client</code>.</li><li><strong>ID im MQTT-Client eintragen:</strong> Öffne <strong>MQTT-Client</strong> in der Home-Assistant-Seitenleiste. Klappe <strong>Übertragung und TLS</strong> auf. Direkt unter <strong>Topic-Präfix</strong> findest du <strong>HA-Label-ID für Zustandsweiterleitung</strong>. Füge dort das Ergebnis aus Schritt 2 ein und klicke <strong>Speichern und verbinden</strong>.</li><li><strong>Label zuweisen:</strong> Öffne <strong>Einstellungen → Geräte &amp; Dienste → Entitäten</strong>, wähle die gewünschte Entität und öffne über das Zahnrad ihre Einstellungen. Wähle <strong>Label hinzufügen → zu mqtt client</strong> und klicke <strong>Aktualisieren</strong>.</li></ol><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">label_id</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zu mqtt client&quot;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="https://www.home-assistant.io/template-functions/label_id/" target="_blank" rel="noreferrer">Home Assistant · label_id</a></p><p>Der Client prüft die Zuordnung im eingestellten Polling-Intervall. Das Label sendet Zustand und Standardattribute und aktiviert passende Rückkanäle. Weitere Attribute bleiben manuell auswählbar. Beim Entfernen des Labels endet die automatische Weiterleitung samt Rückkanälen; manuell ausgewählte Entitäten bleiben aktiv. Den letzten gespeicherten MQTT-Wert kannst du bei Bedarf über die Retain-Bereinigung entfernen.</p><p>Auf Home Assistant <code>.177</code> mit einem separaten MQTT-Broker geprüft: Nach dem Hinzufügen kamen <code>off</code> und <code>on</code> an. Nach dem Entfernen wurde die nächste Zustandsänderung nicht mehr gesendet. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/mqtt-client-v0.1.17" target="_blank" rel="noreferrer">Release 0.1.17</a></p><h2 id="live-ubertragung-und-status" tabindex="-1">Live-Übertragung und Status <a class="header-anchor" href="#live-ubertragung-und-status" aria-label="Permalink to &quot;Live-Übertragung und Status&quot;">​</a></h2><p>Nach dem vollständigen Anfangsstand verarbeitet die App HA-Zustandsänderungen live über WebSocket. Nach einer erneuten HA-Verbindung wird der Anfangsstand neu eingelesen; nach einer MQTT-Neuverbindung werden alle ausgewählten Werte erneut übertragen.</p><p>Bei ausgefallener Live-Verbindung bleibt die bisherige Abfrage als Fallback aktiv: <strong>standardmäßig alle fünf Sekunden</strong>, einstellbar über <code>poll_interval</code> von 1 bis 300 Sekunden. Während einer Unterbrechung oder zwischen Fallback-Abfragen verpasste Änderungen lassen sich nicht nachträglich rekonstruieren. Eine überlastete Ereigniswarteschlange wird angezeigt und löst eine erneute Synchronisierung aus.</p><p>Der Status unterscheidet MQTT-Verbindung und HA-Erreichbarkeit und zeigt Live-/Abfragemodus, letzte Synchronisierung, letzte Veröffentlichung, Anzahl der Veröffentlichungen und bereinigte Fehlertypen. Zugangsdaten und Nachrichteninhalte werden dort nicht ausgegeben.</p><table tabindex="0"><thead><tr><th>MQTT-Thema</th><th>Inhalt</th></tr></thead><tbody><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/state</code></td><td>Zustand als Text</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/attribute/&lt;attribute&gt;</code></td><td>Ausgewähltes Attribut</td></tr><tr><td><code>&lt;topic_prefix&gt;/&lt;device&gt;/&lt;value&gt;/set</code></td><td>Rückkanal für unterstützte Steuerbefehle</td></tr><tr><td><code>&lt;topic_prefix&gt;/availability</code></td><td><code>online</code> nach erfolgreicher HA-Synchronisierung, sonst <code>offline</code></td></tr></tbody></table><p>Standardpräfix ist <code>ha_external</code>. Zustände und Attribute werden mit QoS 1 und Retain veröffentlicht; MQTT-Discovery wird nicht erzeugt. Beim ersten Aufbau kommen Zustände und Attribute vor den <code>/set</code>-Rückkanälen, standardmäßig mit 50 ms Abstand zwischen Veröffentlichungen. <code>unknown</code> und <code>unavailable</code> werden weitergereicht; fehlende Entitäten liefern <code>unavailable</code>.</p><h2 id="steuerbefehle-zuruck-an-ha" tabindex="-1">Steuerbefehle zurück an HA <a class="header-anchor" href="#steuerbefehle-zuruck-an-ha" aria-label="Permalink to &quot;Steuerbefehle zurück an HA&quot;">​</a></h2><p>Für ausgewählte steuerbare Entitäten werden Rückkanäle automatisch aktiviert. Sensoren bleiben reine Ausgänge. Befehle an das passende <code>/set</code>-Thema <strong>ohne Retain</strong> senden.</p><table tabindex="0"><thead><tr><th>Entität</th><th>Nutzdaten</th></tr></thead><tbody><tr><td>Schaltbare Entität</td><td><code>ON</code> oder <code>OFF</code></td></tr><tr><td><code>number</code>, <code>input_number</code></td><td>Zahlenwert</td></tr><tr><td><code>select</code>, <code>input_select</code></td><td>Name einer verfügbaren Option</td></tr><tr><td><code>text</code>, <code>input_text</code></td><td>Text</td></tr><tr><td><code>button</code>, <code>input_button</code></td><td><code>PRESS</code></td></tr><tr><td><code>cover</code></td><td><code>OPEN</code>, <code>CLOSE</code>, <code>STOP</code> oder <code>{&quot;position&quot;:45}</code></td></tr><tr><td><code>light</code></td><td><code>{&quot;brightness_pct&quot;:75}</code></td></tr><tr><td><code>fan</code></td><td><code>{&quot;percentage&quot;:50}</code></td></tr></tbody></table><p>Die JSON-Befehle erlauben jeweils nur das genannte Feld und eine endliche Zahl von 0 bis 100. Das HA-Gerät muss die Funktion unterstützen. Alte Entitäts-ID-Themen wie <code>ha_external/switch.plug/set</code> bleiben gültig. Retained-Befehle, veraltete Befehle und ungültige Inhalte werden verworfen; beliebige HA-Aktionsaufrufe sind nicht vorgesehen.</p><h2 id="veraltete-retain-topics-entfernen" tabindex="-1">Veraltete Retain-Topics entfernen <a class="header-anchor" href="#veraltete-retain-topics-entfernen" aria-label="Permalink to &quot;Veraltete Retain-Topics entfernen&quot;">​</a></h2><p><strong>Veraltete Retain-Topics prüfen</strong> zeigt aufgezeichnete Themen, die durch geänderte Auswahl, Präfixe oder Gerätenamen nicht mehr verwendet werden. Gewünschte Themen markieren und das Löschen bestätigen; höchstens 100 pro Vorgang.</p><p>Die App löscht ausschließlich eigene, erfolgreich bestätigte Veröffentlichungen auf dem aktuell konfigurierten Broker. Aktive und fremde Themen bleiben geschützt. Das Inventar liegt dauerhaft in <code>/data/mqtt-topics.json</code>. Fehlgeschlagene Löschungen bleiben für einen erneuten Versuch erhalten. Es gibt <strong>keine automatische Bereinigung</strong>. Nicht aufgezeichnete Alt-Themen aus der Zeit vor diesem Update müssen weiterhin direkt am Broker entfernt werden.</p><h2 id="einstellungen-sichern-und-wiederherstellen" tabindex="-1">Einstellungen sichern und wiederherstellen <a class="header-anchor" href="#einstellungen-sichern-und-wiederherstellen" aria-label="Permalink to &quot;Einstellungen sichern und wiederherstellen&quot;">​</a></h2><p><strong>Einstellungen sichern</strong> lädt eine JSON-Datei mit Broker-Einstellungen, Client-ID, Themenpräfix, Auswahl, Abfrageintervall, Veröffentlichungsabstand und eigener CA herunter. <strong>Sicherung öffnen</strong> prüft die Datei und fragt vor dem Ersetzen nach.</p><p>Die Datei enthält <strong>kein MQTT-Passwort, kein Client-Zertifikat, keinen privaten Schlüssel und keinen HA-Token</strong>. Sie ist nicht verschlüsselt. Bei gleichem Broker bleiben lokal gespeicherte Zugangsdaten und Client-Zertifikat/Schlüssel erhalten. Bei einem anderen Broker müssen diese neu eingegeben werden. Retained-Inhalte sind nicht enthalten; eine vollständige HA-App-Sicherung wird dadurch nicht ersetzt.</p><h2 id="tls-mit-eigenen-zertifikaten" tabindex="-1">TLS mit eigenen Zertifikaten <a class="header-anchor" href="#tls-mit-eigenen-zertifikaten" aria-label="Permalink to &quot;TLS mit eigenen Zertifikaten&quot;">​</a></h2><p>Unter <strong>Übertragung und TLS</strong> können eigene CA, Client-Zertifikat und privater Schlüssel als PEM-Dateien geladen oder als Text eingefügt werden. Zertifikat und Schlüssel müssen zusammen vorliegen. Der TLS-Port richtet sich nach dem Broker, häufig 8883.</p><p>Serverzertifikat und Hostname werden immer geprüft, mit Systemvertrauen oder eigener CA. Leere Geheimnisfelder behalten gespeicherte Werte. Zum Entfernen die ausdrückliche Option <strong>Gespeicherte TLS-Zertifikate und Schlüssel entfernen</strong> aktivieren und speichern. Ungültige TLS-Konfigurationen werden vor dem Ändern der Einstellungen abgewiesen.</p><h2 id="update-und-kompatibilitat" tabindex="-1">Update und Kompatibilität <a class="header-anchor" href="#update-und-kompatibilitat" aria-label="Permalink to &quot;Update und Kompatibilität&quot;">​</a></h2><p>Bestehende Einstellungen aus 0.1.15 bleiben gültig: Broker-Zugangsdaten, Geräte-/Attributauswahl, Client-ID, Themenpräfix, Abfrageintervall und Veröffentlichungsabstand werden beim Start nicht umgeschrieben. TLS bleibt in seiner bisherigen Einstellung; neue Zertifikatsfelder sind standardmäßig leer. Retained-Daten werden beim Update nicht gelöscht.</p><p>Version 0.1.16 wurde mit Backend-Tests, einem MQTT-Broker, einer WebSocket-Gegenstelle, TLS mit Client-Zertifikat, Weboberfläche und Docker-Start geprüft. Die tatsächliche HA-Installation und die unterstützten Gerätefunktionen müssen mit der eigenen Umgebung geprüft werden.</p>',97)])])}const m=t(s,[["render",l]]);export{p as __pageData,m as default};
